/// Copies the reference vectors in `spec/vectors/*.json` into Dart files the core tests import.
///
///   dart run tool/vectors.dart
///
/// Tests compiled to JavaScript or Wasm run in a browser and cannot read files outside their package,
/// so each vector file is carried as a string constant in `packages/ilchon_core/test/vectors/`.
/// `tool/test/vectors_test.dart` fails when a generated file differs from what this writes.
library;

import 'dart:io';

import 'package:path/path.dart' as p;

const String vectorSource = 'spec/vectors';
const String vectorTarget = 'packages/ilchon_core/test/vectors';

/// The generated files, by path relative to the workspace [root], and their content.
Map<String, String> renderVectors(String root) {
  final sources = Directory(
    p.join(root, vectorSource),
  ).listSync().whereType<File>().map((f) => f.path).where((path) => path.endsWith('.json')).toList()..sort();
  return {
    for (final source in sources)
      p.join(vectorTarget, '${p.basenameWithoutExtension(source)}.g.dart'): _render(
        p.relative(source, from: root),
        File(source).readAsStringSync(),
      ),
  };
}

String _render(String source, String json) {
  if (json.contains("'''")) throw StateError("$source holds ''' and cannot become a raw string");
  final name = '${p.basenameWithoutExtension(source)}Vectors';
  return "// Generated by `dart run tool/vectors.dart` from $source. Do not edit.\n"
      "const String $name = r'''\n$json''';\n";
}

void main(List<String> args) {
  final root = p.normalize(p.absolute(args.isEmpty ? '.' : args.first));
  final target = Directory(p.join(root, vectorTarget));
  if (target.existsSync()) target.deleteSync(recursive: true);
  for (final MapEntry(key: path, value: text) in renderVectors(root).entries) {
    File(p.join(root, path))
      ..parent.createSync(recursive: true)
      ..writeAsStringSync(text);
    stdout.writeln('wrote $path');
  }
}
